  __TTTTTTTTTTTTgggTTTTasTTTTT__
  __TTTTTTTTTTTTTg==sTTTTTTTT___
  __TTx==ggg=TsTTHgTTTTTTT______
  __TT=ggggggg==gggTTT__________
  __TTggggggggg=ggg=TT__________
  __TTggggg=mTTTTTTTTT__________
  __TTggggggTTTTTTTTTT__________
