@warp d -> ruta_2 spawn=north
@warp n -> pueblo_cantera spawn=south
# D1 (contract 68): the fifth Origin Fragment: a shard in the hollow of a stump that only shows at NIGHT (20:00 .. 05:59 by the Flipper's clock: `clock night`, read in the casino plugin).
@script find_night interact
    jf frag_5 empty
    clock night nt
    jv nt 1 night
    say d1.stump.day
    end
  night:
    say d1.stump.night
    give_item origin_shard 1
    jv 0 0 full
    setf frag_5
    sfx item
    say gl.d1.got
    end
  full:
    say gl.found.full
    end
  empty:
    say d1.stump.empty
@end
